// Order status timeline for self-pickup and courier orders. Home delivery has
// its own richer DeliveryPanel; this covers the pickup and courier lifecycles.
// Courier diverges after "Confirmed": Shipped → Received instead of Ready →
// Picked up, so a courier buyer sees the right milestones (and dates).
function OrderStatusPanel({ order }: { order: Order }) {
  const { L } = useLang()
  const approved = order.status === 'approved'
  // Every farmer-fulfilled type now follows the same Shipped → Delivered
  // lifecycle. Rider home deliveries never reach this panel. The only difference
  // is which field stamps the final step (received_at for a shipped order,
  // collected_at for a self-pickup) and the header label.
  const isShippedFlow = order.delivery_type === 'courier' || order.delivery_type === 'home_delivery'
  const collected = !!order.collected_at
  const shipped = !!order.shipped_at
  const received = !!order.received_at
  const delivered = received || collected
  // Online orders that have been paid show an extra "Payment received" step.
  const paidOnline = isOnlinePayment(order.payment_method)
    && (order.payment_status === 'paid' || order.payment_status === 'completed')

  const fmt = (iso?: string | null) =>
    iso ? new Date(iso).toLocaleString('en-IN', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) : ''

  type Step = { label: string; sub: string; at: string; done: boolean }
  const steps: Step[] = [
    { label: L('Order placed', 'ఆర్డర్ పెట్టారు'), sub: L('We received your order', 'మీ ఆర్డర్ అందింది'), at: fmt(order.created_at), done: true },
    ...(paidOnline
      ? [{ label: L('Payment received', 'చెల్లింపు అందింది'), sub: L(`${order.payment_method_detail || 'UPI'} payment confirmed`, `${order.payment_method_detail || 'UPI'} చెల్లింపు ధృవీకరించబడింది`), at: fmt(order.paid_at), done: true }]
      : []),
    { label: L('Confirmed by farmer', 'రైతు ధృవీకరించారు'), sub: L('Farmer accepted your order', 'రైతు అంగీకరించారు'), at: fmt(order.confirmed_at), done: approved },
    { label: L('Shipped', 'షిప్ చేయబడింది'), sub: isShippedFlow
        ? L('Farmer shipped your order to your address', 'రైతు మీ చిరునామాకు పంపారు')
        : L('Farmer has your order ready', 'రైతు మీ ఆర్డర్ సిద్ధం చేశారు'), at: fmt(order.shipped_at), done: shipped },
    { label: L('Delivered', 'డెలివరీ అయింది'), sub: L('You confirmed delivery', 'మీరు డెలివరీ ధృవీకరించారు'), at: fmt(order.received_at || order.collected_at), done: delivered },
  ]

  // Current = the furthest milestone reached (last step marked done).
  let current = 0
  steps.forEach((s, i) => { if (s.done) current = i })

  return (
    <div className="bg-white rounded-2xl border border-gray-100 p-4 space-y-4">
      {/* Header — mirrors the home-delivery panel so every order type's tracker
          looks the same, just with the icon/label for this fulfilment type. */}
      <div className="flex items-center gap-2">
        <span className="text-base">{order.delivery_type === 'home_delivery' ? '🛵' : isShippedFlow ? '📦' : '🧺'}</span>
        <p className="text-xs font-bold text-gray-500 uppercase tracking-wide">
          {order.delivery_type === 'home_delivery'
            ? L('Home delivery', 'ఇంటి డెలివరీ')
            : isShippedFlow ? L('Courier delivery', 'కొరియర్ డెలివరీ') : L('Farm pickup', 'ఫామ్ పికప్')}
        </p>
      </div>

      {/* Prominent completion banner once the order is resolved — same style as
          the "Delivered" banner on the home-delivery tracker. */}

  onFeedback?: (order: ConsumerOrder) => void
  // Acknowledge a declined/cancelled order (moves it to history).
  onAcknowledge?: (order: ConsumerOrder) => void
  // Confirm a shipped order was delivered/received.
  onConfirmReceipt?: (order: ConsumerOrder) => void
  // Cancel a still-pending order (opens the reason modal in the parent).
  onCancel?: (order: ConsumerOrder) => void
  // The parent is mid-request for this card (disables the action buttons).
  busy?: boolean
}) {
  const { tx, lang, L } = useLang()
  const reviewed = Boolean(order.my_review)
  const completed = isCompleted(order)
  const awaitingAck = needsAcknowledge(order)
  // The buyer confirms delivery themselves, once the farmer has marked the order
  // shipped — for every farmer-fulfilled type (self-pickup, courier, farmer-
  // shipped home delivery). Rider home deliveries never set shipped_at (the rider
  // closes them at the door), so they're naturally excluded here.
  const canConfirmReceipt = Boolean(
    onConfirmReceipt
      && order.status !== 'cancelled'
      && order.status !== 'declined'
      && !!order.shipped_at
      && !order.collected_at
      && !order.received_at,
  )
  // Feedback is only offered once the order is completed (delivered / picked up
  // / received). Showing it on a pending order is meaningless — the buyer hasn't
  // received the produce yet. Already-reviewed orders keep the button so the
  // buyer can see / edit what they left.
  const canFeedback = Boolean(onFeedback && order.produce_listing_id && (completed || reviewed))
  // Buyer may cancel any time before the order is shipped or handed over
  // (pending or approved-and-awaiting). Shared rule with the detail page + API.
  const canCancel = Boolean(onCancel && canBuyerCancel(order))

